import unittest

import math_ops


class GcdListTests(unittest.TestCase):
    def test_empty(self):
        self.assertEqual(math_ops.gcd_list([]), 0)

    def test_single_positive(self):
        self.assertEqual(math_ops.gcd_list([7]), 7)

    def test_single_negative(self):
        self.assertEqual(math_ops.gcd_list([-7]), 7)

    def test_single_zero(self):
        self.assertEqual(math_ops.gcd_list([0]), 0)

    def test_multiple_positive(self):
        self.assertEqual(math_ops.gcd_list([12, 18, 24]), 6)

    def test_multiple_mixed_signs(self):
        self.assertEqual(math_ops.gcd_list([-12, 18, -24]), 6)

    def test_with_zero(self):
        self.assertEqual(math_ops.gcd_list([0, 5, 10]), 5)

    def test_all_zeros(self):
        self.assertEqual(math_ops.gcd_list([0, 0, 0]), 0)


class LcmListTests(unittest.TestCase):
